var s = 16;
var density = 40;
var maxHeight;
var N_FRAMES = 128;

function setup() {
  createCanvas(512, 512);
  noStroke();
}

function draw() {
  let t = TAU*frameCount/N_FRAMES;
  let yStep = height/8;
  maxHeight = yStep - 2*s;

  blendMode(BLEND);
  background(0);

  blendMode(ADD);
  for (let c of [[255, 0, 0], [0, 255, 0], [0, 0, 255]]) {
    for (let y = 0; y < height; y += (Math.max(0.001, Math.abs(yStep)) || 1)) {
      fill(c);
      drawLinesDown(t, y);
      drawLinesUp(t+PI, y+yStep);
      t *= -1;
    }
    t += 0.2;
  }

  blendMode(DIFFERENCE);
  fill(255);
  for (let y = 0; y < height; y += (Math.max(0.001, Math.abs(2*yStep)) || 1)) {
    rect(0, y, width, yStep);
  }
}

function drawLinesUp(t, y0) {
  for (let x = 0; x < width; x += (Math.max(0.001, Math.abs(2*s)) || 1)) {
    let h = map(cos(x/density+t), -1, 1, 0, maxHeight);
    let y = y0 - h;
    rect(x, y, s, h);
    arc(x+s/2, y, s, s, PI, TAU);
  }
}

function drawLinesDown(t, y0) {
  for (let x = s; x < width; x += (Math.max(0.001, Math.abs(2*s)) || 1)) {
    var h = map(cos(x/density+t), -1, 1, 0, maxHeight);
    var y = y0 + h;
    rect(x, y0, s, h);
    arc(x+s/2, y, s, s, 0, PI);
  }
}
